mapper.sql:
FROM BANNER_MST
WHERE DEL_DT IS NULL

	AND USE_YN = #{useYn}


	AND PSTG_BGNG_YMD >= STR_TO_DATE(#{startPublishDate}, '%Y-%m-%d')


	AND PSTG_END_YMD <= STR_TO_DATE(#{endPublishDate}, '%Y-%m-%d')


	AND DATE(REG_DT) >= #{startRegDate}


	AND DATE(REG_DT) <= #{endRegDate}




			AND BNR_NM LIKE CONCAT('%', #{searchKeyword}, '%')


			AND (BNR_MAIN_CN LIKE CONCAT('%', #{searchKeyword}, '%') OR BNR_SUB_CN LIKE CONCAT('%', #{searchKeyword}, '%'))


			AND (BNR_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR BNR_MAIN_CN LIKE CONCAT('%', #{searchKeyword}, '%') OR BNR_SUB_CN LIKE CONCAT('%', #{searchKeyword}, '%'))

mapper.select:
SELECT


ORDER BY SORT_SEQ ASC, REG_DT DESC
LIMIT #{offset}, #{limit}
